-- A26: estado opaco do anexo; não retorna chave, URL, nome, tipo, tamanho ou conteúdo.
drop function public.subdivision_list_buyer_attachment_intents(uuid,uuid,public.operating_module,text);
create or replace function public.subdivision_list_buyer_attachment_intents(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(attachment_intent_id uuid,buyer_client_id uuid,created_at timestamptz,attachment_state text) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,buyer_client_id,created_at,case when storage_key is null then 'awaiting_private_upload' else 'private_upload_recorded' end from public.subdivision_buyer_attachment_intents where organization_id=p_organization_id order by created_at desc;end;$$;
revoke all on function public.subdivision_list_buyer_attachment_intents(uuid,uuid,public.operating_module,text) from public,anon,authenticated;
grant execute on function public.subdivision_list_buyer_attachment_intents(uuid,uuid,public.operating_module,text) to service_role;
